insert into public.skills (id, name, type, source_type, mp_cost, damage_formula, effect, skill_description, skill_shape, "range", aoe_radius, projectile_speed, cooldown_seconds, arc_angle_degrees, target_attack, target_effect, stat_modifiers, periodic_effects, control_effects, special_effects, usage_requirements, sort_order)
values ('spore_cloud_aura', 'Spore Cloud Aura', 'Passive', 'Monster', 0, '0', 'A protective spore veil increases the user''s DEF by 8%.', 'A protective spore veil increases the user''s DEF by 8%.', 'passive', 0.0, 0.0, 0.0, 0.0, NULL, 'none', 'self', '[{"stat": "def", "value": 8, "type": "percent", "duration_turns": 0, "target": "self", "condition": "-"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"allowed_classes": [], "min_level": 1, "allowed_weapons": [], "allowed_races": []}'::jsonb, 688)
on conflict (id) do update set name=excluded.name, type=excluded.type, source_type=excluded.source_type, mp_cost=excluded.mp_cost, damage_formula=excluded.damage_formula, effect=excluded.effect, skill_description=excluded.skill_description, skill_shape=excluded.skill_shape, "range"=excluded."range", aoe_radius=excluded.aoe_radius, projectile_speed=excluded.projectile_speed, cooldown_seconds=excluded.cooldown_seconds, arc_angle_degrees=excluded.arc_angle_degrees, target_attack=excluded.target_attack, target_effect=excluded.target_effect, stat_modifiers=excluded.stat_modifiers, periodic_effects=excluded.periodic_effects, control_effects=excluded.control_effects, special_effects=excluded.special_effects, usage_requirements=excluded.usage_requirements, sort_order=excluded.sort_order;
update public.monsters set skill_set = jsonb_set(skill_set, '{passive_skills,0,skill_id}', '"spore_cloud_aura"'::jsonb)
where monster_id=5004 and skill_set #>> '{passive_skills,0,skill_id}' = 'spore_cloud';
do $combat_audit$
begin
  if exists (select 1 from public.skills where nullif(btrim(skill_description), '') is null) then
    raise exception 'Combat audit: skill descriptions are still empty';
  end if;
  if not exists (select 1 from public.skills where id='spore_cloud_aura' and type='Passive') then
    raise exception 'Combat audit: missing Spore Cloud passive';
  end if;
  if not exists (select 1 from public.monsters where monster_id=5004 and skill_set #>> '{passive_skills,0,skill_id}'='spore_cloud_aura') then
    raise exception 'Combat audit: Wild Mushroom passive reference not updated';
  end if;
  if exists (select 1 from public.allies a left join public.skills p on p.id=a.passive_skill_id
    left join public.skills s on s.id=a.active_skill_id
    where p.id is null or s.id is null or p.type <> 'Passive' or s.type <> 'Active') then
    raise exception 'Combat audit: invalid ally skill references';
  end if;
end;
$combat_audit$;
commit;
